mapper.select:
select count(*)
from round_seat rs
join seat s on rs.seat_id = s.seat_id
where rs.round_id = #{round_id}
and s.seat_group_id = #{seat_group_id}

mapper.update:
UPDATE round_seat SET status = #{status}
, reservation_id = NULL , preempted_at = NULL , reserved_at = NULL , canceled_at = NULL
, preempted_at = NOW()
, reserved_at = NOW()
, canceled_at = NOW()
WHERE round_id = #{round_id} AND seat_id = #{seat_id}

UPDATE round_seat 
SET seat_state = #{seat_state} 
WHERE seat_id = #{seat_id}
